-- Generated by Lycoles observation-contract recovery
-- Evidence-bounded client helper. No remote fabrication or authority claims.
local CONTRACT = __CONTRACT__
local Players = game:GetService("Players")
local HttpService = game:GetService("HttpService")
local UserInputService = game:GetService("UserInputService")
local player = Players.LocalPlayer
assert(game.PlaceId == __PLACE_ID__, "Wrong place for generated script package")
if type(_G.LycolesMuscleAutoTrainClose) == "function" then pcall(_G.LycolesMuscleAutoTrainClose) end

local timing = CONTRACT.timing or {}
local SETTINGS = {
    activationIntervalSeconds = tonumber(timing.activationIntervalSeconds) or 0.25,
    delayedOutcomeWindowSeconds = tonumber(timing.delayedOutcomeWindowSeconds) or 1.5,
    stallWindowSeconds = tonumber(timing.stallWindowSeconds) or 18.0,
    pollIntervalSeconds = tonumber(timing.pollIntervalSeconds) or 0.2,
    minActivationIntervalSeconds = tonumber(timing.minActivationIntervalSeconds) or 0.1,
    maxActivationIntervalSeconds = tonumber(timing.maxActivationIntervalSeconds) or 2.0,
}

local function clamp(value, minValue, maxValue)
    if value < minValue then return minValue end
    if value > maxValue then return maxValue end
    return value
end

local function round(value, digits)
    local p = 10 ^ (digits or 0)
    return math.floor(value * p + 0.5) / p
end

local function splitPath(path)
    local parts = {}
    for token in string.gmatch(path or "", "[^%.]+") do
        parts[#parts + 1] = token
    end
    return parts
end

local function resolvePath(path)
    if type(path) ~= "string" or path == "" then return nil, "empty path" end
    local parts = splitPath(path)
    if #parts == 0 then return nil, "invalid path" end

    local root = nil
    local index = 2
    if parts[1] == "LocalPlayer" then
        root = player
    elseif parts[1] == "Workspace" then
        root = workspace
    elseif parts[1] == "ReplicatedStorage" then
        root = game:GetService("ReplicatedStorage")
    elseif parts[1] == "Character" then
        root = player.Character
    elseif parts[1] == "Backpack" then
        root = player:FindFirstChild("Backpack")
    elseif player:FindFirstChild(parts[1]) then
        root = player
        index = 1
    else
        root = player:FindFirstChild("PlayerGui")
        index = 1
    end
    if not root then return nil, "missing root" end

    local current = root
    for i = index, #parts do
        current = current:FindFirstChild(parts[i])
        if not current then return nil, "missing segment: " .. tostring(parts[i]) end
    end
    return current, nil
end

local function readNumber(path)
    local obj = resolvePath(path)
    if not obj then return nil end

    if obj:IsA("ValueBase") then
        local ok, value = pcall(function() return obj.Value end)
        if ok then
            if type(value) == "number" then return value end
            if type(value) == "boolean" then return value and 1 or 0 end
        end
    end

    if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
        local text = string.lower(string.gsub(obj.Text or "", "%s+", ""))
        local numeric = tonumber(text)
        if numeric ~= nil then return numeric end
        if text == "ready" or text == "claim" then return 1 end
        if text == "claimed" then return 0 end
        local mm, ss = string.match(text, "^(%d+):(%d+)$")
        if mm and ss then
            return (tonumber(mm) or 0) * 60 + (tonumber(ss) or 0)
        end
        local hh, mm2, ss2 = string.match(text, "^(%d+):(%d+):(%d+)$")
        if hh and mm2 and ss2 then
            return (tonumber(hh) or 0) * 3600 + (tonumber(mm2) or 0) * 60 + (tonumber(ss2) or 0)
        end
    end

    if obj:IsA("GuiObject") then
        return obj.Visible and 1 or 0
    end

    return nil
end

local function resolveTool(toolPath, toolName)
    local exact = nil
    if type(toolPath) == "string" and toolPath ~= "" then
        exact = resolvePath(toolPath)
    end
    if exact and exact:IsA("Tool") then
        return exact
    end

    local candidates = {player:FindFirstChild("Backpack"), player.Character}
    for _, parent in ipairs(candidates) do
        if parent then
            for _, child in ipairs(parent:GetChildren()) do
                if child:IsA("Tool") and child.Name == toolName then
                    return child
                end
            end
        end
    end
    return nil
end

local function activateGuiObject(obj)
    if not obj then return false, "nil object" end
    if not obj:IsA("GuiButton") then return false, "object is not GuiButton" end

    if type(firesignal) == "function" then
        local okClick = pcall(function()
            if obj.MouseButton1Click then
                firesignal(obj.MouseButton1Click)
            end
        end)
        if okClick then return true, "firesignal.MouseButton1Click" end

        local okActivated = pcall(function()
            if obj.Activated then
                firesignal(obj.Activated)
            end
        end)
        if okActivated then return true, "firesignal.Activated" end
    end

    local okActivate, activateErr = pcall(function() obj:Activate() end)
    if okActivate then
        return true, "GuiButton.Activate"
    end

    return false, "no-supported-gui-trigger: " .. tostring(activateErr)
end

local function activateGuiPath(path)
    local obj, err = resolvePath(path)
    if not obj then return false, "resolve failed: " .. tostring(err) end
    return activateGuiObject(obj)
end

local state = {
    alive = true,
    startClock = os.clock(),
    currentStrength = nil,
    initialStrength = nil,
    totalStrengthGain = 0,
    strengthGainPerMinute = 0,
    lastProgression = "none",
    stalled = false,
    intervalScale = 1.0,
    lastStatus = "ready",
}

local runtimeCapabilities = {
    firesignal = (type(firesignal) == "function"),
    setclipboard = (type(setclipboard) == "function" or type(toclipboard) == "function" or type(toClipboard) == "function"),
}

local features = {}
local featureOrder = {}
local rows = {}
local connections = {}

local function featureRuntime(definition, supported)
    local action = definition.action or {}
    return {
        id = tostring(definition.id or "feature"),
        title = tostring(definition.title or definition.id or "Feature"),
        supported = supported,
        includeInStartAll = definition.includeInStartAll == true,
        destructive = definition.destructive == true,
        definition = definition,
        action = action,
        attempts = 0,
        successes = 0,
        successfulCalls = 0,
        errors = 0,
        progressEvents = 0,
        progressTotal = 0,
        progressionByUnit = {},
        unresolvedPaths = {},
        lastProgress = "none",
        lastError = nil,
        outcomeState = supported and "action-invoked-outcome-unverified" or "unsupported-interaction",
        lastStatus = supported and "idle" or "unavailable",
        verifiedOutcomes = 0,
        unverifiedOutcomes = 0,
        blockedOutcomes = 0,
        unsupportedOutcomes = 0,
        runtimeFailureOutcomes = 0,
        lastInvokeAt = nil,
        pendingVerification = false,
        verifyEventSnapshot = 0,
        running = false,
        token = 0,
        cursor = 0,
        intervalSeconds = tonumber(action.intervalSeconds) or SETTINGS.activationIntervalSeconds,
        monitorValues = {},
        monitorPaths = {},
    }
end

local featureDependencies = CONTRACT.featureDependencies or {}

for _, definition in ipairs(CONTRACT.featureContracts or {}) do
    local feature = featureRuntime(definition, definition.supported ~= false)
    local monitor = definition.monitor or {}
    if type(monitor.primaryOutcomePath) == "string" then
        feature.monitorPaths[#feature.monitorPaths + 1] = monitor.primaryOutcomePath
    end
    for _, path in ipairs(monitor.candidateStatePaths or {}) do
        if type(path) == "string" then
            feature.monitorPaths[#feature.monitorPaths + 1] = path
        end
    end
    for _, path in ipairs(monitor.questRepetitionStatePaths or {}) do
        if type(path) == "string" then
            feature.monitorPaths[#feature.monitorPaths + 1] = path
        end
    end
    features[feature.id] = feature
    featureOrder[#featureOrder + 1] = feature
end

for _, unsupported in ipairs(CONTRACT.unsupportedFeatures or {}) do
    if features[unsupported.id] == nil then
        local definition = {
            id = unsupported.id,
            title = unsupported.title,
            includeInStartAll = false,
            destructive = false,
            action = {kind = "none"},
            evidence = unsupported.evidence,
        }
        local feature = featureRuntime(definition, false)
        features[feature.id] = feature
        featureOrder[#featureOrder + 1] = feature
    end
end

local globalStrengthPath = ((CONTRACT.outcomeModel or {}).primaryStatePath)

local function updateGlobalProgression()
    local value = readNumber(globalStrengthPath)
    if value ~= nil then
        if state.currentStrength ~= nil and value > state.currentStrength then
            local delta = value - state.currentStrength
            state.totalStrengthGain += delta
            state.lastProgression = string.format("+%s Strength", tostring(round(delta, 3)))
        end
        state.currentStrength = value
        if state.initialStrength == nil then state.initialStrength = value end
    end
    local elapsed = math.max(0.01, os.clock() - state.startClock)
    state.strengthGainPerMinute = (state.totalStrengthGain / elapsed) * 60
end

local function classifyProgressUnit(path)
    local low = string.lower(path or "")
    if string.find(low, "strength", 1, true) then return "strength" end
    if string.find(low, ".reps.progress", 1, true) then return "reps" end
    if string.find(low, ".minutes.progress", 1, true) then return "minutes" end
    if string.find(low, "agility", 1, true) then return "agility" end
    if string.find(low, ".claimed", 1, true) then return "claimed" end
    return "other"
end

local function refreshFeatureProgress(feature)
    for _, path in ipairs(feature.monitorPaths) do
        local value = readNumber(path)
        if value ~= nil then
            local previous = feature.monitorValues[path]
            if previous ~= nil and value > previous then
                local delta = value - previous
                local unit = classifyProgressUnit(path)
                feature.progressEvents += 1
                feature.progressTotal += delta
                feature.progressionByUnit[unit] = (feature.progressionByUnit[unit] or 0) + delta
                feature.lastProgress = string.format("%s (+%s %s)", path, tostring(round(delta, 3)), unit)
            end
            feature.monitorValues[path] = value
            feature.unresolvedPaths[path] = nil
        else
            feature.unresolvedPaths[path] = true
        end
    end
end

local function markOutcome(feature, stateName, statusText)
    feature.outcomeState = stateName
    if statusText then
        feature.lastStatus = statusText
    end
    if stateName == "action-verified-in-gameplay" then
        feature.verifiedOutcomes += 1
    elseif stateName == "action-invoked-outcome-unverified" then
        feature.unverifiedOutcomes += 1
    elseif stateName == "blocked-by-eligibility" then
        feature.blockedOutcomes += 1
    elseif stateName == "unsupported-interaction" then
        feature.unsupportedOutcomes += 1
    elseif stateName == "runtime-failure" then
        feature.runtimeFailureOutcomes += 1
    end
end

local function armVerification(feature)
    feature.pendingVerification = true
    feature.lastInvokeAt = os.clock()
    feature.verifyEventSnapshot = feature.progressEvents
end

local function reconcileVerification(feature)
    if not feature.pendingVerification then return end
    local outcomeContract = feature.definition.outcomeContract or {}
    local window = tonumber(outcomeContract.verificationWindowSeconds) or math.max(2.0, SETTINGS.delayedOutcomeWindowSeconds * 2.0)

    if feature.progressEvents > (feature.verifyEventSnapshot or 0) then
        feature.pendingVerification = false
        markOutcome(feature, "action-verified-in-gameplay", "outcome verified by state delta")
        return
    end

    if feature.lastInvokeAt and (os.clock() - feature.lastInvokeAt) >= window then
        feature.pendingVerification = false
        markOutcome(feature, "action-invoked-outcome-unverified", "action sent; no verified reward-state change")
    end
end


local function executeFeature(feature)
    local action = feature.action or {}
    local kind = action.kind
    feature.attempts += 1

    if kind == "tool_activate" then
        local tool = resolveTool(action.toolPath, action.toolName)
        if not tool then
            feature.errors += 1
            feature.lastError = "tool unavailable"
            markOutcome(feature, "runtime-failure", "tool unavailable")
            return
        end
        local humanoid = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
        if humanoid and tool.Parent ~= player.Character then
            pcall(function() humanoid:EquipTool(tool) end)
            task.wait(0.05)
        end
        local ok, err = pcall(function() tool:Activate() end)
        if not ok then
            feature.errors += 1
            feature.lastError = tostring(err)
            markOutcome(feature, "runtime-failure", "activation failed")
            return
        end
        feature.successes += 1
        feature.successfulCalls += 1
        feature.outcomeState = "action-invoked-outcome-unverified"
        feature.lastStatus = "activation sent"
        return
    end

    if kind == "cycle_tool_activate" then
        local toolPaths = action.toolPaths or {}
        if #toolPaths == 0 then
            markOutcome(feature, "blocked-by-eligibility", "no alternate tools discovered")
            return
        end
        feature.cursor = (feature.cursor % #toolPaths) + 1
        local targetPath = toolPaths[feature.cursor]
        local tool = resolveTool(targetPath, nil)
        if not tool or not tool:IsA("Tool") then
            feature.errors += 1
            feature.lastError = "alternate tool unavailable"
            markOutcome(feature, "runtime-failure", "alternate tool unavailable")
            return
        end
        local humanoid = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
        if humanoid and tool.Parent ~= player.Character then
            pcall(function() humanoid:EquipTool(tool) end)
            task.wait(0.05)
        end
        local ok, err = pcall(function() tool:Activate() end)
        if not ok then
            feature.errors += 1
            feature.lastError = tostring(err)
            markOutcome(feature, "runtime-failure", "alternate tool activation failed")
            return
        end
        feature.successes += 1
        feature.successfulCalls += 1
        feature.outcomeState = "action-invoked-outcome-unverified"
        feature.lastStatus = "alternate tool activation sent"
        return
    end

    if kind == "ensure_tool_equipped" then
        local tool = resolveTool(action.toolPath, action.toolName)
        local humanoid = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
        if not tool or not humanoid then
            feature.errors += 1
            feature.lastError = "tool or humanoid unavailable"
            markOutcome(feature, "runtime-failure", "equip unavailable")
            return
        end
        local ok, err = pcall(function() humanoid:EquipTool(tool) end)
        if not ok then
            feature.errors += 1
            feature.lastError = tostring(err)
            markOutcome(feature, "runtime-failure", "equip failed")
            return
        end
        feature.successes += 1
        feature.successfulCalls += 1
        feature.outcomeState = "action-invoked-outcome-unverified"
        feature.lastStatus = "equip requested"
        return
    end

    if kind == "auto_rewards_discovery" then
        local candidates = {}
        local seen = {}

        local function pushCandidate(obj)
            if not obj or not obj:IsA("GuiButton") then return end
            if seen[obj] then return end
            local lowName = string.lower(obj.Name or "")
            if string.find(lowName, "buy", 1, true) or string.find(lowName, "robux", 1, true) or string.find(lowName, "vip", 1, true) then
                return
            end
            if string.find(lowName, "spin", 1, true) or string.find(lowName, "wheel", 1, true) then
                return
            end
            seen[obj] = true
            candidates[#candidates + 1] = obj
        end

        for _, path in ipairs(action.paths or {}) do
            local obj = resolvePath(path)
            pushCandidate(obj)
        end

        for _, containerPath in ipairs(action.rewardContainerPaths or {}) do
            local container = resolvePath(containerPath)
            if container then
                for _, descendant in ipairs(container:GetDescendants()) do
                    local lowName = string.lower(descendant.Name or "")
                    if descendant:IsA("GuiButton") and (
                        string.find(lowName, "hitbox", 1, true)
                        or string.find(lowName, "claim", 1, true)
                        or string.find(lowName, "collect", 1, true)
                    ) then
                        pushCandidate(descendant)
                    end
                end
            end
        end

        local function isEligible(obj)
            if not obj.Visible then return false, "hidden" end
            local parent = obj.Parent
            if not parent then return true, "no-parent" end

            local claimed = parent:FindFirstChild("Claimed", true)
            if claimed and claimed:IsA("GuiObject") and claimed.Visible then
                return false, "already-claimed"
            end

            local timer = parent:FindFirstChild("Timer", true)
            if timer and timer:IsA("TextLabel") then
                local text = string.lower(timer.Text or "")
                if text ~= "" and text ~= "0" and text ~= "00:00" and text ~= "00:00:00" then
                    return false, "cooldown"
                end
            end

            local readyText = parent:FindFirstChild("ReadyText", true)
            if readyText and readyText:IsA("GuiObject") then
                if readyText.Visible then return true, "ready-text-visible" end
                if readyText:IsA("TextLabel") and string.find(string.lower(readyText.Text or ""), "ready", 1, true) then
                    return true, "ready-text-content"
                end
            end

            return true, "no-indicator"
        end

        local function listenerCount(obj)
            if type(getconnections) ~= "function" then return nil end
            local total = 0
            local okClick, clickConnections = pcall(function() return getconnections(obj.MouseButton1Click) end)
            if okClick and type(clickConnections) == "table" then total += #clickConnections end
            local okActivated, activatedConnections = pcall(function() return getconnections(obj.Activated) end)
            if okActivated and type(activatedConnections) == "table" then total += #activatedConnections end
            return total
        end

        if #candidates == 0 then
            markOutcome(feature, "blocked-by-eligibility", "no reward candidates")
            return
        end

        feature.cursor = (feature.cursor % #candidates) + 1
        local target = candidates[feature.cursor]
        local eligible, reason = isEligible(target)
        if not eligible then
            markOutcome(feature, "blocked-by-eligibility", "reward not eligible: " .. tostring(reason))
            return
        end

        local listeners = listenerCount(target)
        if listeners ~= nil and listeners <= 0 and not runtimeCapabilities.firesignal then
            markOutcome(feature, "unsupported-interaction", "no reward listeners and no firesignal")
            return
        end

        local ok, methodOrErr = activateGuiObject(target)
        if not ok then
            feature.errors += 1
            feature.lastError = tostring(methodOrErr)
            if string.find(tostring(methodOrErr), "no-supported-gui-trigger", 1, true) then
                markOutcome(feature, "unsupported-interaction", "reward trigger unsupported")
            else
                markOutcome(feature, "runtime-failure", "reward trigger runtime failure")
            end
            return
        end

        feature.successes += 1
        feature.successfulCalls += 1
        feature.lastStatus = "reward trigger sent via " .. tostring(methodOrErr)
        feature.outcomeState = "action-invoked-outcome-unverified"
        armVerification(feature)
        return
    end

    if kind == "quest_train_workflow" then
        local autoTrainFeature = features["auto_train"]
        if not autoTrainFeature or not autoTrainFeature.running then
            markOutcome(feature, "blocked-by-eligibility", "auto_train dependency not running")
            return
        end

        local questPaths = action.questOpenPaths or {}
        if #questPaths > 0 then
            feature.cursor = (feature.cursor % #questPaths) + 1
            local questPath = questPaths[feature.cursor]
            local qOk, qErr = activateGuiPath(questPath)
            if qOk then
                feature.successfulCalls += 1
                feature.successes += 1
                feature.outcomeState = "action-invoked-outcome-unverified"
                feature.lastStatus = "quest interface action sent"
                return
            end
            feature.lastError = tostring(qErr)
            if string.find(tostring(qErr), "no-supported-gui-trigger", 1, true) then
                markOutcome(feature, "unsupported-interaction", "quest interface trigger unsupported")
            else
                markOutcome(feature, "runtime-failure", "quest interface action failed")
            end
            return
        end

        feature.successes += 1
        feature.outcomeState = "action-invoked-outcome-unverified"
        feature.lastStatus = "quest monitoring via auto_train dependency"
        return
    end


    if kind == "gui_activate_many" then
        local paths = action.paths or {}
        if #paths == 0 then
            markOutcome(feature, "blocked-by-eligibility", "no actionable GUI paths")
            return
        end
        feature.cursor = (feature.cursor % #paths) + 1
        local ok, err = activateGuiPath(paths[feature.cursor])
        if not ok then
            feature.errors += 1
            feature.lastError = tostring(err)
            if string.find(tostring(err), "no-supported-gui-trigger", 1, true) then
                markOutcome(feature, "unsupported-interaction", "gui activation unsupported")
            else
                markOutcome(feature, "runtime-failure", "gui activation failed")
            end
            return
        end
        feature.successes += 1
        feature.successfulCalls += 1
        feature.outcomeState = "action-invoked-outcome-unverified"
        feature.lastStatus = "gui activation sent"
        return
    end

    if kind == "gui_sequence" then
        local steps = action.steps or {}
        if #steps == 0 then
            markOutcome(feature, "blocked-by-eligibility", "no sequence steps")
            return
        end
        for _, step in ipairs(steps) do
            if step.kind == "gui_activate" then
                local ok, err = activateGuiPath(step.path)
                if not ok then
                    feature.errors += 1
                    feature.lastError = tostring(err)
                    if string.find(tostring(err), "no-supported-gui-trigger", 1, true) then
                        markOutcome(feature, "unsupported-interaction", "sequence trigger unsupported")
                    else
                        markOutcome(feature, "runtime-failure", "sequence failed")
                    end
                    return
                end
                feature.successfulCalls += 1
                task.wait(0.05)
            end
        end
        feature.successes += 1
        feature.outcomeState = "action-invoked-outcome-unverified"
        feature.lastStatus = "sequence sent"
        return
    end

    if kind == "observe_only" then
        feature.outcomeState = "action-invoked-outcome-unverified"
        feature.lastStatus = "monitor only"
        return
    end

    feature.outcomeState = "action-invoked-outcome-unverified"
    feature.lastStatus = "monitor only"
end

local function stopFeature(feature, reason)
    feature.running = false
    feature.pendingVerification = false
    feature.token += 1
    feature.lastStatus = reason or feature.lastStatus
end

local function startFeature(feature, visited)
    if not feature.supported then
        feature.lastStatus = "unavailable"
        return
    end
    if feature.running then
        feature.lastStatus = "already running"
        return
    end

    visited = visited or {}
    if visited[feature.id] then return end
    visited[feature.id] = true

    local dependencies = featureDependencies[feature.id] or {}
    for _, dependencyId in ipairs(dependencies) do
        local dependencyFeature = features[dependencyId]
        if dependencyFeature and not dependencyFeature.running then
            startFeature(dependencyFeature, visited)
        end
    end

    if feature.destructive then
        local now = os.clock()
        feature.confirmUntil = feature.confirmUntil or 0
        if now > feature.confirmUntil then
            feature.confirmUntil = now + 5.0
            markOutcome(feature, "blocked-by-eligibility", "confirmation required: press START again within 5s")
            return
        end
        feature.confirmUntil = 0
    end

    feature.running = true
    feature.token += 1
    local token = feature.token
    feature.lastStatus = "running"
    task.spawn(function()
        while state.alive and feature.running and token == feature.token do
            executeFeature(feature)
            local waitTime = clamp(feature.intervalSeconds * state.intervalScale, SETTINGS.minActivationIntervalSeconds, SETTINGS.maxActivationIntervalSeconds)
            task.wait(waitTime)
        end
    end)
end

local function startAll()
    for _, feature in ipairs(featureOrder) do
        if feature.supported and feature.includeInStartAll and not feature.destructive then
            startFeature(feature)
        end
    end
    state.lastStatus = "start-all issued"
end

local function stopAll(reason)
    for _, feature in ipairs(featureOrder) do
        if feature.running then
            stopFeature(feature, reason or "stopped")
        end
    end
end

local function buildDiagnosticReport()
    local featureReports = {}
    local successfulApiCalls = 0
    local runtimeErrors = {}
    local observedStateChanges = {}

    for _, feature in ipairs(featureOrder) do
        successfulApiCalls += feature.successfulCalls
        if feature.lastError then
            runtimeErrors[#runtimeErrors + 1] = {featureId = feature.id, message = feature.lastError}
        end
        local unresolved = {}
        for path, unresolvedFlag in pairs(feature.unresolvedPaths or {}) do
            if unresolvedFlag then unresolved[#unresolved + 1] = path end
        end

        observedStateChanges[#observedStateChanges + 1] = {
            featureId = feature.id,
            progressionEvents = feature.progressEvents,
            progressionTotal = round(feature.progressTotal, 6),
            progressionByUnit = feature.progressionByUnit,
            unresolvedPaths = unresolved,
            lastProgression = feature.lastProgress,
        }
        featureReports[#featureReports + 1] = {
            id = feature.id,
            title = feature.title,
            supported = feature.supported,
            includeInStartAll = feature.includeInStartAll,
            destructive = feature.destructive,
            attempts = feature.attempts,
            successes = feature.successes,
            successfulApiCalls = feature.successfulCalls,
            errors = feature.errors,
            progressionEvents = feature.progressEvents,
            progressionTotal = round(feature.progressTotal, 6),
            progressionByUnit = feature.progressionByUnit,
            unresolvedPaths = unresolved,
            status = feature.lastStatus,
            outcomeState = feature.outcomeState,
            outcomeCounters = {
                verified = feature.verifiedOutcomes,
                unverified = feature.unverifiedOutcomes,
                blocked = feature.blockedOutcomes,
                unsupported = feature.unsupportedOutcomes,
                runtimeFailure = feature.runtimeFailureOutcomes,
            },
            actionable = feature.definition.actionable,
            evidence = feature.definition.evidence,
        }
    end

    local sessionStrengthNetChange = nil
    if state.currentStrength ~= nil and state.initialStrength ~= nil then
        sessionStrengthNetChange = round(state.currentStrength - state.initialStrength, 6)
    end

    local attributedStrengthTotal = 0
    for _, feature in ipairs(featureOrder) do
        attributedStrengthTotal += tonumber(feature.progressionByUnit.strength or 0) or 0
    end

    return {
        schemaVersion = "lycoles.batch-diagnostic.1",
        game = {
            gameName = CONTRACT.gameName,
            placeId = CONTRACT.placeId,
            gameId = game.GameId,
        },
        versions = {
            inspectorSchemaVersion = ((CONTRACT.generatorMetadata or {}).inspectorSchemaVersion),
            projectVersion = ((CONTRACT.generatorMetadata or {}).projectVersion),
            generatorVersion = ((CONTRACT.generatorMetadata or {}).generatorVersion),
        },
        generatedFeatureList = CONTRACT.generatedFeatureIds or {},
        featureDependencies = CONTRACT.featureDependencies or {},
        deduplicatedFeatures = CONTRACT.deduplicatedFeatures or {},
        runtimeCapabilities = runtimeCapabilities,
        featureReports = featureReports,
        successfulApiCalls = successfulApiCalls,
        runtimeErrors = runtimeErrors,
        observedStateChanges = observedStateChanges,
        delayedProgressionOutcomes = {
            strengthPath = globalStrengthPath,
            strengthPathResolved = (state.currentStrength ~= nil),
            currentStrength = state.currentStrength,
            initialStrength = state.initialStrength,
            totalStrengthGain = round(state.totalStrengthGain, 6),
            sessionStrengthNetChange = sessionStrengthNetChange,
            strengthGainPerMinute = round(state.strengthGainPerMinute, 6),
            stalled = state.stalled,
        },
        progressionAccounting = {
            positiveStrengthDeltaObserved = round(state.totalStrengthGain, 6),
            sessionStrengthNetChange = sessionStrengthNetChange,
            featureAttributedStrengthDeltaSum = round(attributedStrengthTotal, 6),
            attributionOvercountEstimate = round(attributedStrengthTotal - state.totalStrengthGain, 6),
        },
        unsupportedFeatures = CONTRACT.unsupportedFeatures or {},
        claims = CONTRACT.claims,
    }
end

local function exportDiagnosticReport()
    local encoded = HttpService:JSONEncode(buildDiagnosticReport())
    local copied = false
    if type(setclipboard) == "function" then
        pcall(function() setclipboard(encoded) end)
        copied = true
    elseif type(toclipboard) == "function" then
        pcall(function() toclipboard(encoded) end)
        copied = true
    elseif type(toClipboard) == "function" then
        pcall(function() toClipboard(encoded) end)
        copied = true
    end
    _G.LycolesLastDiagnosticReport = encoded
    if copied then
        state.lastStatus = "diagnostic report copied"
    else
        state.lastStatus = "clipboard unavailable; report printed and cached"
        print(encoded)
    end
end

